def majority_element(nums):
    """Return the value that appears more than len(nums) / 2 times in nums."""
    ...

solution:
def majority_element(nums):
    candidate, votes = None, 0
    for x in nums:
        if votes == 0:
            candidate = x                       # nobody is ahead right now, so the current value takes over
        votes += 1 if x == candidate else -1    # a different value cancels one vote for the candidate
    return candidate
